function bloomsOnArrival(flowers: number[][], visits: number[]): number[] {
  const starts = flowers.map(f => f[0]).sort((a, b) => a - b);
  const ends = flowers.map(f => f[1]).sort((a, b) => a - b);
  // number of values in sorted arr that are < x (strict) or <= x
  const countBelow = (arr: number[], x: number, inclusive: boolean): number => {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (arr[mid] < x || (inclusive && arr[mid] === x)) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  };
  return visits.map(t => countBelow(starts, t, true) - countBelow(ends, t, false));
}

