function bloomsOnArrival(flowers: number[][], visits: number[]): number[] {
  const starts = flowers.map(f => f[0]).sort((a, b) => a - b);
  const ends = flowers.map(f => f[1]).sort((a, b) => a - b);
  const order = visits.map((_, i) => i).sort((a, b) => visits[a] - visits[b]);
  const out = new Array(visits.length).fill(0);
  let s = 0, e = 0;
  for (const j of order) {
    const t = visits[j];
    while (s < starts.length && starts[s] <= t) s++;
    while (e < ends.length && ends[e] < t) e++;
    out[j] = s - e;
  }
  return out;
}

